int count = template.queryForObject(
        "select count(*) from item", Integer.class);

// 객체 하나
Item item = template.queryForObject(
        "select id, item_name, price, quantity from item where id = ?",
        itemRowMapper(), id);

// 여럿
List<Item> items = template.query(
        "select id, item_name, price, quantity from item",
        itemRowMapper());

// 값 여럿
List<String> names = template.queryForList(
        "select item_name from item", String.class);

String sql = "insert into item (item_name, price, quantity) values (?, ?, ?)";

List<Object[]> batchArgs = items.stream()
        .map(i -> new Object[]{i.getItemName(), i.getPrice(), i.getQuantity()})
        .toList();

int[] counts = template.batchUpdate(sql, batchArgs);

